import{mountShell}from'../shared/shell.js?v=0.8.0';import{readStore,writeStore,downloadText}from'../shared/utils.js?v=0.8.0';import{lineChart}from'../model-kit/chart.js?v=0.8.0';import{create,validate,simulate,assess,edges,OFFSETS}from'./engine.js?v=0.8.0';mountShell({active:'adoption'});const app=document.querySelector('#app'),KEY='thinking-lab:adoption:v1';let saved=readStore(KEY,null),s,baseline,round=0,past=[],selected=2,message='';try{s=validate(saved?.s||create());baseline=saved?.baseline?validate(saved.baseline):null;}catch{s=create();baseline=null;}const f=x=>x.toFixed(1),pos=Array.from({length:12},(_,i)=>{const a=(i%6)*Math.PI/3-Math.PI/2;return{x:(i<6?27:73)+Math.cos(a)*16,y:50+Math.sin(a)*32};});function save(){if(!writeStore(KEY,{s,baseline}))message='Storage unavailable. Export to keep this experiment.';}function change(fn,msg){past.push({s:structuredClone(s),baseline:structuredClone(baseline)});past=past.slice(-40);fn();validate(s);round=0;message=msg||'New starting conditions. Step through to see what happens.';save();render();}function render(){const r=simulate(s),b=baseline?simulate(baseline):null;round=Math.min(round,r.rounds);const now=r.history[round],rows=assess(s,now),row=rows[selected];app.innerHTML=`<section class="surface"><div class="toolbar"><button class="primary" id="step" ${round>=r.rounds?'disabled':''}>Step one round</button><button id="run">Run to outcome</button><button id="rewind">Back to pilot</button><button id="pin">Pin this plan</button><button id="undo" ${!past.length?'disabled':''}>Undo</button><button id="reset">Reset</button></div><p class="status" role="status">${message||'Tap people to add or remove them from the starting pilot. The two clusters coordinate mostly within their own group.'}</p><div class="network-wrap"><div class="network" aria-label="Adoption network"><svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none">${edges(s).map(([a,b])=>`<line class="${Math.floor(a/6)!==Math.floor(b/6)?'bridge':''}" x1="${pos[a].x}" y1="${pos[a].y}" x2="${pos[b].x}" y2="${pos[b].y}"></line>`).join('')}</svg><span class="cluster one">Group A</span><span class="cluster two">Group B</span>${pos.map((p,i)=>`<button class="person ${now[i]?'adopted':''} ${s.seeds.includes(i)?'seed':''}" data-person="${i}" style="left:${p.x}%;top:${p.y}%" aria-pressed="${s.seeds.includes(i)}" aria-label="Person ${i+1}, ${now[i]?'using new':'using old'}, ${s.seeds.includes(i)?'in pilot; remove':'not in pilot; add'}"><b>${String(i+1).padStart(2,'0')}</b><small>${s.seeds.includes(i)?'Pilot':now[i]?'New':'Old'}</small></button>`).join('')}</div></div><div class="toolbar"><span class="hint">Filled = using new · outlined = pilot · lines = coordination partners</span><button id="bridge" aria-pressed="${s.bridge}">${s.bridge?'Remove':'Add'} two links between groups</button><button id="clear">Clear pilot</button></div><div class="field timeline"><label for="round">Inspect round <output>${round} / ${r.rounds} · ${round===r.rounds?r.status:'before next decisions'}</output></label><input id="round" type="range" min="0" max="${r.rounds}" value="${round}"></div></section><section class="metrics"><div class="metric"><span>Using new now</span><strong>${now.filter(Boolean).length}/12</strong><small>At inspected round ${round}</small></div><div class="metric"><span>Starting pilot</span><strong>${s.seeds.length}</strong><small>${s.hold?'Pilot stays committed':'Pilot can switch back'}</small></div><div class="metric"><span>Outcome after ${r.rounds} rounds</span><strong>${r.final.filter(Boolean).length}/12</strong><small>${r.status}${b?` · pinned ${b.final.filter(Boolean).length}/12`:''}</small></div><div class="metric"><span>Potential utility of new alone</span><strong>${f(s.benefit)}</strong><small>Before personal differences or coordination</small></div></section><div class="split"><section class="surface"><h2>What makes switching worthwhile?</h2><div class="fields">${[['benefit','Standalone benefit',0,12,.5],['coordination','Value of coordinating',0,12,.5],['switching','One-time switching friction',0,6,.5],['compatibility','New works with old',0,1,.1]].map(([k,l,min,max,step])=>`<div class="field"><label for="${k}">${l} <output>${f(s[k])}</output></label><input data-param="${k}" id="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}"></div>`).join('')}</div><label class="hold"><input type="checkbox" id="hold" ${s.hold?'checked':''}> Pilot participants stay committed</label><p>Compatibility gives new users some coordination value with old users. Old users still benefit only from old partners.</p></section><section class="surface"><h2>Inspect one person’s next choice</h2><label for="person-select">Person</label> <select id="person-select">${pos.map((_,i)=>`<option value="${i}" ${i===selected?'selected':''}>${String(i+1).padStart(2,'0')} · group ${i<6?'A':'B'}</option>`).join('')}</select><table class="reason"><tr><td>Partners using new</td><td>${Math.round(row.share*100)}%</td></tr><tr><td>New utility</td><td>${f(row.newValue)}</td></tr><tr><td>Old utility</td><td>${f(row.oldValue)}</td></tr><tr><td>New minus old</td><td>${f(row.gain)}</td></tr><tr><td>Cost to change either way</td><td>${f(s.switching)}</td></tr></table><p><strong>${row.held?'Stays new as a committed pilot participant.':row.next===row.current?`Stays with ${row.current?'new':'old'}; the gain from changing does not exceed friction.`:`Switches to ${row.next?'new':'old'}; the gain exceeds friction.`}</strong></p><p class="hint">Personal standalone benefit: ${f(row.personal)}. Decisions are simultaneous, based on partners before the round.</p></section></div><section class="surface"><h2>Adoption over rounds</h2><div class="chart" role="img" aria-label="Number of people adopting over the rounds, current and pinned plans">${lineChart([{values:r.history.map(x=>x.filter(Boolean).length)},...(b?[{values:b.history.map(x=>x.filter(Boolean).length),color:'var(--muted)',dashed:true}]:[])],{min:0,max:12,labels:['Pilot',`Round ${Math.max(r.rounds,b?.rounds||0)}`],cursor:round})}</div><p class="hint">Solid line: current plan. Dashed line: pinned plan. Each sequence uses the same twelve people; pinned assumptions stay fixed for comparison.</p></section><details><summary>Mechanism and limits</summary><p>Let q be the fraction of a person’s partners using new. New utility = personal benefit + coordination × [q + compatibility × (1 − q)]. Old utility = coordination × (1 − q). A person changes only if the other choice’s utility exceeds their current one by more than switching friction. Ties keep the current choice. A held pilot stays new regardless.</p><p>Personal benefit = the standalone setting plus these fixed differences in person order: ${OFFSETS.join(', ')}. The network has two fully connected groups of six; optional bridges join 03–07 and 06–10. Choices update simultaneously until stable, a cycle repeats, or 24 rounds pass. Costs affect the decision to switch; the model does not accumulate money or welfare.</p><p>This is a deterministic coordination sketch with complete local information, fixed preferences and no persuasion, uncertainty, budget or learning. Compatibility is intentionally one-way; other designs can change the result.</p></details><p class="local-note">Pilot, assumptions and baseline save in this browser. Changing them starts a fresh replay.</p>`;bind();}function bind(){app.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>{const id=+el.dataset.person;selected=id;change(()=>s.seeds=s.seeds.includes(id)?s.seeds.filter(x=>x!==id):[...s.seeds,id],'Pilot changed. The network restarts from these people.');});app.querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>{const k=el.dataset.param,v=+el.value;change(()=>s[k]=v);});document.querySelector('#step').onclick=()=>{round++;render();};document.querySelector('#run').onclick=()=>{round=simulate(s).rounds;render();};document.querySelector('#rewind').onclick=()=>{round=0;render();};document.querySelector('#round').onchange=ev=>{round=+ev.target.value;render();};document.querySelector('#person-select').onchange=ev=>{selected=+ev.target.value;render();};document.querySelector('#bridge').onclick=()=>change(()=>s.bridge=!s.bridge);document.querySelector('#hold').onchange=ev=>{const value=ev.target.checked;change(()=>s.hold=value);};document.querySelector('#clear').onclick=()=>change(()=>s.seeds=[]);document.querySelector('#pin').onclick=()=>change(()=>baseline=structuredClone(s),'Plan pinned. Change the pilot, network or assumptions to compare.');document.querySelector('#undo').onclick=()=>{const p=past.pop();if(p){s=p.s;baseline=p.baseline;round=0;save();render();}};document.querySelector('#reset').onclick=()=>change(()=>s=create(),'Initial situation restored.');}document.querySelector('#export').onclick=()=>downloadText('adoption-gap.md',`# Crossing the adoption gap\n\nFictional twelve-person coordination model. Simultaneous choices with switching friction.\n\n\`\`\`json\n${JSON.stringify({settings:s,baseline,result:simulate(s),comparison:baseline?simulate(baseline):null},null,2)}\n\`\`\`\n`.replaceAll('\n','\n'),'text/markdown');render();
